insert into public.weekly_paintings (week_start, card_id, varnish_url, patch_urls, artist_options, story, story_de) values ('2026-11-16', '4jz2ah5m5r', 'art/wk-af40659fc9-varnish.jpg', ARRAY['art/wk-af40659fc9-p0.png', 'art/wk-af40659fc9-p1.png', 'art/wk-af40659fc9-p2.png', 'art/wk-af40659fc9-p3.png', 'art/wk-af40659fc9-p4.png', 'art/wk-af40659fc9-p5.png', 'art/wk-af40659fc9-p6.png'], ARRAY['Nicolas Poussin', 'Tintoretto', 'Parmigianino', 'Johannes Vermeer'], 'In seventeenth-century Delft, imaginary character studies in exotic dress were called tronies. Two quick dabs of white paint make the pearl catch the light against the dark ground.', 'Im Delft des 17. Jahrhunderts nannte man solche Fantasiefiguren mit Turban ein Tronie. Zwei helle Farbtupfer reichen Vermeer, damit die Perle vor dem dunklen Grund aufleuchtet.') on conflict (week_start) do update set card_id = excluded.card_id, varnish_url = excluded.varnish_url, patch_urls = excluded.patch_urls, artist_options = excluded.artist_options, story = excluded.story, story_de = excluded.story_de;
insert into public.weekly_paintings (week_start, card_id, varnish_url, patch_urls, artist_options, story, story_de) values ('2026-11-23', '9pwzh5hdpw', 'art/wk-f09b63beda-varnish.jpg', ARRAY['art/wk-f09b63beda-p0.png', 'art/wk-f09b63beda-p1.png', 'art/wk-f09b63beda-p2.png', 'art/wk-f09b63beda-p3.png', 'art/wk-f09b63beda-p4.png', 'art/wk-f09b63beda-p5.png', 'art/wk-f09b63beda-p6.png'], ARRAY['Damien Hirst', 'Vincent van Gogh', 'Elias Garcia Martinez', 'Norman Rockwell'], 'Van Gogh painted this swirling night sky from memory while looking out of his room in Saint-Rémy. The dark cypress tree and the quiet village spire anchor the restless sky.', 'Van Gogh malte diesen wirbelnden Nachthimmel aus dem Gedächtnis nach dem Blick aus seinem Zimmer in Saint-Rémy. Die dunkle Zypresse und der Kirchturm geben dem unruhigen Himmel Halt.') on conflict (week_start) do update set card_id = excluded.card_id, varnish_url = excluded.varnish_url, patch_urls = excluded.patch_urls, artist_options = excluded.artist_options, story = excluded.story, story_de = excluded.story_de;
insert into public.weekly_paintings (week_start, card_id, varnish_url, patch_urls, artist_options, story, story_de) values ('2026-11-30', 'ey272y9qy3', 'art/wk-e0b7c44611-varnish.jpg', ARRAY['art/wk-e0b7c44611-p0.png', 'art/wk-e0b7c44611-p1.png', 'art/wk-e0b7c44611-p2.png', 'art/wk-e0b7c44611-p3.png', 'art/wk-e0b7c44611-p4.png', 'art/wk-e0b7c44611-p5.png', 'art/wk-e0b7c44611-p6.png'], ARRAY['Sandro Botticelli', 'Artemisia Gentileschi', 'Hieronymus Bosch', 'Ambrogio Lorenzetti'], 'Botticelli painted the goddess arriving ashore on a scallop shell blown by gentle winds. His flowing lines and bright tempera colours look more like a dream than a heavy oil painting.', 'Botticelli malte die Göttin auf einer Muschel, die vom Wind ans Ufer getragen wird. Seine fließenden Linien und hellen Temperafarben lassen das Werk wie einen Traum wirken.') on conflict (week_start) do update set card_id = excluded.card_id, varnish_url = excluded.varnish_url, patch_urls = excluded.patch_urls, artist_options = excluded.artist_options, story = excluded.story, story_de = excluded.story_de;
insert into public.weekly_paintings (week_start, card_id, varnish_url, patch_urls, artist_options, story, story_de) values ('2026-12-07', '5t2zrhnc2m', 'art/wk-b90a0e1b6b-varnish.jpg', ARRAY['art/wk-b90a0e1b6b-p0.png', 'art/wk-b90a0e1b6b-p1.png', 'art/wk-b90a0e1b6b-p2.png', 'art/wk-b90a0e1b6b-p3.png', 'art/wk-b90a0e1b6b-p4.png', 'art/wk-b90a0e1b6b-p5.png', 'art/wk-b90a0e1b6b-p6.png'], ARRAY['Caspar David Friedrich', 'Élisabeth Vigée Le Brun', 'Utagawa Hiroshige', 'Jean-Honoré Fragonard'], 'Friedrich placed the lone traveller with his back turned so that you step straight into his boots. The misty peaks around him come from sketches he drew in the Elbe Sandstone Mountains.', 'Friedrich zeigt den einsamen Wanderer von hinten, damit du selbst an seiner Stelle stehst. Die nebligen Gipfel ringsum entstanden nach Skizzen aus dem Elbsandsteingebirge.') on conflict (week_start) do update set card_id = excluded.card_id, varnish_url = excluded.varnish_url, patch_urls = excluded.patch_urls, artist_options = excluded.artist_options, story = excluded.story, story_de = excluded.story_de;
